-- Import du rapport MP COSMETIQUE (fichier "1 INV MP COSMETIQUE.xlsx"
-- fourni par l'utilisateur) - 193 articles. A executer APRES
-- create_rapport_gamme_statistique_mp.sql, dans Supabase SQL Editor.

on conflict (gamme_statistique, ordre) do update set
  designation = excluded.designation,
  categorie = excluded.categorie,
  donnees = excluded.donnees;
